solution:
function solve(a, b) {
  const hasil = []
  let i = 0 // penunjuk di a
  let j = 0 // penunjuk di b
  while (i < a.length && j < b.length) {
    if (a[i] <= b[j]) hasil.push(a[i++])
    else hasil.push(b[j++])
  }
  while (i < a.length) hasil.push(a[i++])
  while (j < b.length) hasil.push(b[j++])
  return hasil
}
